package main

import "fmt"

func edges() {
	base := func() darksafe.ReleasePlanInput {
		return darksafe.ReleasePlanInput{
			App: "payments-gateway", Revision: "r3",
			Image: "img:r3", BatchSize: 2, SpreadBy: "zone",
			Include: []darksafe.LabelCondition{{"env": "prod"}},
		}
	}

	// 1) 空候选列表：Validate 成功，MakeReleasePlan 失败
	empty := base()
	fmt.Printf("empty candidates: ValidateReleaseInput -> %v\n", darksafe.ValidateReleaseInput(empty))
	plan, err := darksafe.MakeReleasePlan(empty)
	fmt.Printf("empty candidates: MakeReleasePlan    -> err=%v plan=%+v\n", err, plan)

	// 2a) 重复标识，且重复项已停用
	dupDisabled := base()
	dupDisabled.Clusters = []darksafe.Cluster{
		{ID: "c-a", Tags: map[string]string{"env": "prod", "zone": "east"}},
		{ID: "c-a", Disabled: true},
	}
	_, err = darksafe.MakeReleasePlan(dupDisabled)
	fmt.Printf("duplicate (later disabled): %v\n", err)

	// 2b) 重复标识，且重复项会被包含条件筛掉
	dupFiltered := base()
	dupFiltered.Clusters = []darksafe.Cluster{
		{ID: "c-a", Tags: map[string]string{"env": "prod", "zone": "east"}},
		{ID: "c-a", Tags: map[string]string{"env": "dev"}},
	}
	_, err = darksafe.MakeReleasePlan(dupFiltered)
	fmt.Printf("duplicate (later filtered): %v\n", err)

	// 3) 空标识 / 只含空白标识
	for _, id := range []string{"", "   ", "\t"} {
		bad := base()
		bad.Clusters = []darksafe.Cluster{{ID: id}}
		fmt.Printf("id=%q -> %v\n", id, darksafe.ValidateReleaseInput(bad))
	}

	// 4) 大小写、首尾空格不同 = 不同集群，均合法
	distinct := base()
	distinct.Clusters = []darksafe.Cluster{
		{ID: "c-a", Tags: map[string]string{"env": "prod", "zone": "east"}},
		{ID: "C-A", Tags: map[string]string{"env": "prod", "zone": "west"}},
		{ID: " c-a ", Tags: map[string]string{"env": "prod", "zone": "north"}},
	}
	p, err := darksafe.MakeReleasePlan(distinct)
	fmt.Printf("case/space distinct ids -> err=%v batches=%v\n", err, p.Batches)
}
